/* From Uiverse.io by reshades - Tags: OTP, form, animated, clean, verify, Verification */
.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: #00000000;
  border-radius: 16px;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(8.2px);
  -webkit-backdrop-filter: blur(8.2px);
  border: 1px solid #369eff66;
  width: 14em;
  height: 14em;
}

.__UIV_SCOPE__ .content {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: auto;
  margin-bottom: auto;
}

.__UIV_SCOPE__ .form p {
  color: #fff;
  font-weight: bolder;
}

.__UIV_SCOPE__ .path {
  fill: #369eff
}

.__UIV_SCOPE__ .svg {
  filter: blur(20px);
  z-index: -1;
  position: absolute;
  opacity: 50%;
  animation: anim 3s infinite;
}

.__UIV_SCOPE__ .inp {
  margin-left: auto;
  margin-right: auto;
  white-space: 4px;
}

.__UIV_SCOPE__ .input + .input {
  margin-left: 0.3em
}

.__UIV_SCOPE__ .input {
  color: #fff;
  height: 2em;
  width: 2em;
  float: left;
  text-align: center;
  background: #00000000;
  outline: none;
  border: 1px #369eff solid;
  border-radius: 10px;
  transition: all 0.6s ease;
}

.__UIV_SCOPE__ .input:focus {
  outline: none;
  border: 1px #fff solid;
}

.__UIV_SCOPE__ .input:not(:placeholder-shown) {
  opacity: 40%
}

.__UIV_SCOPE__ .form button {
  margin-left: auto;
  margin-right: auto;
  background-color: #00000000;
  color: #fff;
  width: 8.5em;
  height: 2.3em;
  border: #369eff 0.2em solid;
  border-radius: 11px;
  transition: all 0.5s ease;
}

.__UIV_SCOPE__ .form button:hover {
  background-color: #369eff;
}

@keyframes anim {
  0% {
    transform: translateY(-70px);
  }

  50% {
    transform: translateY(-19px);
  }

  100% {
    transform: translateY(-70px);
  }
}
